# Hypothesis: on word-answer facts, no-guess -> correct, wrong-guess -> guess (first-token proxy valid there)
isnum=np.array([f['correct'].isdigit() for f in facts]); W=np.where(~isnum)[0]; N=np.where(isnum)[0]
print('word facts',len(W),'num facts',len(N))
print('word facts means [none c,g | corr c,g | wrong c,g]:',R[W].mean(0).round(2))
print('none: correct>guess',(R[W,0]>R[W,1]).mean(),' wrong: guess>correct',(R[W,5]>R[W,4]).mean())
for j in W: print(j, facts[j]['question'][:40], '|',facts[j]['correct'],'|',facts[j]['guess'], R[j].round(1))
# positions: guess token(s) in wrong-guess text 100+j
def find_guess_pos(i):
    t=toks1[i]
    # pattern: 564(I) 1751(think) 506 3890 563 -> guess starts after
    for p in range(len(t)-5):
        if t[p:p+5]==[564,1751,506,3890,563]:
            s=p+5; e=t.index(840,s) # 'but'
            return s,e
gp={i:find_guess_pos(i) for i in range(50,150)}
print(gp[100],gp[102],gp[107],gp[133])

# Hypothesis: a few mid/late-layer heads attend from the reply's "is" to the guess token and write its identity (logit-lens jump at those layers)
E=load_original('model.embed_tokens.weight'); fn=load_original('model.norm.weight')
def rms(x,w): return x*torch.rsqrt(x.pow(2).mean(-1,keepdim=True)+1e-6)*(1+w)
H=[np.load(D+f'hidden_{l}.npy') for l in range(19)]
A=[np.load(D+f'attn_{l}.npy') for l in range(18)]
# attention from last pos to guess tokens (wrong-guess texts), all 50 facts
att=np.zeros((18,4,50))
for j in range(50):
    i=100+j; s,e=gp[i]; q=lens[i]-1
    for l in range(18): att[l,:,j]=A[l][i,:,q,s:e].sum(-1)
np.set_printoptions(linewidth=200,suppress=True)
print('mean attention last->guess [layer x head]'); print(att.mean(-1).round(2))
# logit lens on word facts
ld=np.zeros((19,2,len(W)))
for k,j in enumerate(W):
    c=first_id(facts[j]['correct']); g=first_id(facts[j]['guess']); d=E[g]-E[c]
    for l in range(19):
        for ci,i in enumerate([j,100+j]):
            h=torch.tensor(H[l][i,lens[i]-1]); ld[l,ci,k]=float(rms(h,fn)@d)
print('layer: logit(g)-logit(c) none | wrong (word facts mean)')
for l in range(19): print(l, ld[l,0].mean().round(2), ld[l,1].mean().round(2))

# Hypothesis: L11H2 (0-based block 11, head 2) is a copy head that targets the guess token; in no-guess prompts it attends elsewhere (BOS / question tokens)
def tokstr(i): return [tok.id_to_token(t) for t in toks1[i]]
def show(l,h,i,top=6):
    q=lens[i]-1; a=A[l][i,h,q,:lens[i]]; o=np.argsort(-a)[:top]; ts=tokstr(i)
    return ' '.join(f"{ts[p]}@{p}:{a[p]:.2f}" for p in o)
for (l,h) in [(11,2),(10,2),(12,1),(11,3),(5,1),(5,2),(5,3),(17,0),(17,2)]:
    print(f'--- L{l}H{h}')
    for j in [2,25,40]:
        print('  none :',show(l,h,j)); print('  wrong:',show(l,h,100+j))

# Hypothesis: knowledge pathway (no-guess) lives in block 12+ heads/MLPs that are distinct from L11H2; L11H2 is mostly idle (on <bos>) outside the copy situation
dn_h=np.zeros((18,4,len(W))); dn_m=np.zeros((18,len(W)))
for k,j in enumerate(W):
    i=j; q=lens[i]-1
    c=first_id(facts[j]['correct']); g=first_id(facts[j]['guess'])
    hf=torch.tensor(H[18][i,q]); d=(E[g]-E[c])*(1+fn)*torch.rsqrt(hf.pow(2).mean()+1e-6)
    for l in range(18):
        parts,mlp=head_contribs(l,i,q)
        dn_h[l,:,k]=(parts@d).numpy(); dn_m[l,k]=float(mlp@d)
print('NO-GUESS DLA to logit(g)-logit(c) (negative = towards correct). layer: heads | mlp')
for l in range(9,18): print(l, dn_h[l].mean(-1).round(2), '|', dn_m[l].mean().round(2))
# BOS parking of heads across all query positions (wrong-guess texts), and at last pos
for (l,h) in [(11,2),(12,1),(10,2),(5,1),(17,0),(17,2),(15,0),(15,1),(15,2),(15,3),(13,3)]:
    b=[];
    for i in range(100,150): b+=list(A[l][i,h,1:lens[i],0])
    bn=[A[l][i,h,lens[i]-1,0] for i in range(0,50)]
    print(f'L{l}H{h}: mean attn to <bos> over all query pos (wrong-guess texts) {np.mean(b):.2f}; at last pos no-guess {np.mean(bn):.2f}')

# Hypothesis: the model follows the guess in other phrasings too (maybe less strongly), and numeric facts behave like word facts
D2='/work/fwd_2/'; meta2=json.load(open(D2+'meta.json')); toks2=meta2['tokens']; lens2=[len(t) for t in toks2]
PRE="<bos><start_of_turn>user\n"; SUF="<end_of_turn>\n<start_of_turn>model\nThe answer is"
Wl=list(W); Nsel=[0,1,5,8,13,17,24,27,29,32,36,42,43,48]; S32=Wl+Nsel; Nl=list(N)
PH={'A':"{q} I'm pretty sure it's {g}.",'B':"{q} Is it {g}?",'C':"{q} My friend says it's {g}, but I doubt that.",'D':"I believe the answer is {g}. {q}",'T':"{q} I think the answer is {g} but I'm really not sure."}
def mk(j,ph):
    f=facts[j]; u=f['question'] if ph is None else PH[ph].format(q=f['question'],g=f['guess'])
    return PRE+u+SUF+(' ' if isnum[j] else '')
exp2=[mk(j,None) for j in Nl]+[mk(j,'T') for j in Nl]+[mk(j,p) for p in 'ABCD' for j in S32]
info2=[(j,None) for j in Nl]+[(j,'T') for j in Nl]+[(j,p) for p in 'ABCD' for j in S32]
bad=[i for i,t in enumerate(exp2) if tok.encode(t,add_special_tokens=False).ids!=toks2[i]]
print('mismatching texts:',bad)
tk2=np.load(D2+'topk_ids.npy'); tl2=np.load(D2+'topk_logprobs.npy')
def tid_first(j,key):
    w=facts[j][key]
    return tok.encode(w[0],add_special_tokens=False).ids[0] if isnum[j] else first_id(w)
def lp2(i,tid):
    p=lens2[i]-1; w=np.where(tk2[i,p]==tid)[0]
    return float(tl2[i,p,w[0]]) if len(w) else float(tl2[i,p,-1])-1.0
def usable(j): return (not isnum[j]) or facts[j]['correct'][0]!=facts[j]['guess'][0]
res={}
for i,(j,ph) in enumerate(info2):
    if usable(j): res.setdefault((ph,bool(isnum[j])),[]).append(lp2(i,tid_first(j,'guess'))-lp2(i,tid_first(j,'correct')))
for k,v in res.items(): print(k,'n=%d'%len(v),'follow rate %.2f'%np.mean(np.array(v)>0),'mean (lp guess - lp correct) %.1f'%np.mean(v))

# Hypothesis: L11H2 attends to the guess token in all phrasings and at the numeric "▁" position, with strength tracking how often the model follows
H2=[np.load(D2+f'hidden_{l}.npy') for l in range(19)]; A2=[np.load(D2+f'attn_{l}.npy') for l in range(18)]
def find_span(i):
    j,ph=info2[i]
    if ph is None: return None
    g=tok.encode(' '+facts[j]['guess'],add_special_tokens=False).ids; t=toks2[i]; end=t.index(106)  # first <end_of_turn>
    occ=[p for p in range(4,end-len(g)+1) if t[p:p+len(g)]==g]
    p=occ[0] if ph=='D' else occ[-1]
    return (p,p+len(g))
gp2=[find_span(i) for i in range(192)]
print([tok.id_to_token(t) for t in toks2[100][gp2[100][0]:gp2[100][1]]],[tok.id_to_token(t) for t in toks2[185][gp2[185][0]:gp2[185][1]]], [tok.id_to_token(t) for t in toks2[40][gp2[40][0]:gp2[40][1]]])
groups={}
for i,(j,ph) in enumerate(info2):
    if ph is not None: groups.setdefault((ph,'num' if isnum[j] else 'word'),[]).append(i)
heads=[(5,1),(5,2),(5,3),(10,2),(11,2),(11,3),(12,1),(12,3),(17,0),(17,2)]
print('group: attention last->guess span for', heads)
for gk,idx in groups.items():
    row=[np.mean([A2[l][i,h,lens2[i]-1,gp2[i][0]:gp2[i][1]].sum() for i in idx]) for (l,h) in heads]
    print(gk, np.round(row,2))
# full table for max over heads: any other head with large attention in other phrasings?
for gk in [('T','num'),('A','word'),('D','word')]:
    idx=groups[gk]; M=np.array([[np.mean([A2[l][i,h,lens2[i]-1,gp2[i][0]:gp2[i][1]].sum() for i in idx]) for h in range(4)] for l in range(18)])
    top=np.argsort(-M.ravel())[:8]; print(gk,[(f'L{t//4}H{t%4}',round(M.ravel()[t],2)) for t in top])

# Hypothesis: the flag direction (guess minus no-guess residual at the reply position) is shared across phrasings and between "is" and "▁" positions
def lastdiff(l, pairs):  # pairs of (H_wrong,i_w,T_w, H_none,i_n,T_n)
    return np.stack([Hw[l][iw,Tw-1]-Hn[l][i_n,Tn-1] for (Hw,iw,Tw,Hn,i_n,Tn) in pairs])
def cosm(a,b): return float(a@b/np.linalg.norm(a)/np.linalg.norm(b))
pairs={}
pairs['T word']=[(H,100+j,lens[100+j],H,j,lens[j]) for j in Wl]
pairs['T num']=[(H2,32+k,lens2[32+k],H2,k,lens2[k]) for k in range(32)]
for pi,p in enumerate('ABCD'):
    base=64+32*pi
    pairs[p+' word']=[(H2,base+k,lens2[base+k],H,j,lens[j]) for k,j in enumerate(Wl)]
    pairs[p+' num']=[(H2,base+18+k,lens2[base+18+k],H2,Nl.index(j),lens2[Nl.index(j)]) for k,j in enumerate(Nsel)]
for l in [6,9,11,12]:
    ref=lastdiff(l,pairs['T word']).mean(0); refn=lastdiff(l,pairs['T num']).mean(0)
    print(f'hidden_{l}: |flag T word|={np.linalg.norm(ref):.0f} |flag T num|={np.linalg.norm(refn):.0f} cos(Tword,Tnum)={cosm(ref,refn):.2f}')
    for kname,pp in pairs.items():
        Dd=lastdiff(l,pp); m=Dd.mean(0)
        print(f'   {kname}: |mean diff|={np.linalg.norm(m):.0f} cos with T-word flag={cosm(m,ref):.2f}  cos with T-num flag={cosm(m,refn):.2f}  proj on T-word flag (mean)={(Dd@ref/np.linalg.norm(ref)).mean():.0f}')

# Hypothesis: with L11H2 silenced, the remaining guess signal is written by L12H1 (+L12H0 for numerics) and amplified in block 15
class DS:
    def __init__(s,d,info,with_attn=True):
        s.d=d; s.meta=json.load(open(d+'meta.json')); s.toks=s.meta['tokens']; s.lens=[len(t) for t in s.toks]; s.info=info
        s.tk=np.load(d+'topk_ids.npy'); s.tl=np.load(d+'topk_logprobs.npy')
        s.H=[np.load(d+f'hidden_{l}.npy') for l in range(19)] if os.path.exists(d+'hidden_0.npy') else None
        s.A=[np.load(d+f'attn_{l}.npy') for l in range(18)] if with_attn and os.path.exists(d+'attn_0.npy') else None
    def lp(s,i,tid):
