def ridge_fit(X_, y_, w_, rl):
    Xw = X_ * w_[:, None]
    A_ = X_.T @ Xw
    lam_ = rl * np.trace(A_) / X_.shape[1]
    return np.linalg.solve(A_ + lam_ * np.eye(X_.shape[1]), Xw.T @ y_)
